module currency_exchange(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [31:0] n,\n    input wire [7:0] d,\n    input wire [7:0] e,\n    output reg [7:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE           = 3'd0;\n    localparam [2:0] COMPUTE_N_MOD  = 3'd1;\n    localparam [2:0] LOOP_INIT      = 3'd2;\n    localparam [2:0] LOOP_BODY      = 3'd3;\n    localparam [2:0] LOOP_CHECK     = 3'd4;\n    localparam [2:0] DONE           = 3'd5;\n\n    reg [2:0] state, next_state;\n\n    // Registers for input storage\n    reg [31:0] n_reg;\n    reg [7:0] d_reg, e_reg;\n\n    // Computed values\n    reg [15:0] B_reg;\n    reg [7:0] n_mod_d;\n\n    // Loop variables\n    reg [7:0] i;\n    reg [15:0] iB_total;\n    reg [7:0] iB_mod_d;\n    reg [7:0] min_rem;\n\n    // Mod computation variables\n    reg [4:0] bit_counter;\n    reg [31:0] temp_n;\n    reg [7:0] remainder_temp;\n\n    // Rem calculation\n    wire [8:0] diff = {1'b0, n_mod_d} - {1'b0, iB_mod_d};\n    wire [7:0] rem = (diff[8] ? (diff + d_reg) : diff) % d_reg;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 8'd0;\n            n_reg <= 32'd0;\n            d_reg <= 8'd0;\n            e_reg <= 8'd0;\n            B_reg <= 16'd0;\n            n_mod_d <= 8'd0;\n            i <= 8'd0;\n            iB_total <= 16'd0;\n            iB_mod_d <= 8'd0;\n            min_rem <= 8'hFF;\n            bit_counter <= 5'd31;\n            temp_n <= 32'd0;\n            remainder_temp <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    min_rem <= 8'hFF;\n                    if (start) begin\n                        n_reg <= n;\n                        d_reg <= d;\n                        e_reg <= e;\n                        B_reg <= 5 * e;\n                        temp_n <= n;\n                        remainder_temp <= 8'd0;\n                        bit_counter <= 5'd31;\n                        state <= COMPUTE_N_MOD;\n                    end\n                end\n\n                COMPUTE_N_MOD: begin\n                    bit_counter <= bit_counter - 5'd1;\n                    // Calculate next remainder value\n                    if ({remainder_temp, 1'b0} | (temp_n[bit_counter] ? 1'b1 : 1'b0) >= d_reg) begin\n                        remainder_temp <= {remainder_temp, 1'b0} | (temp_n[bit_counter] ? 1'b1 : 1'b0) - d_reg;\n                    end else begin\n                        remainder_temp <= {remainder_temp, 1'b0} | (temp_n[bit_counter] ? 1'b1 : 1'b0);\n                    end\n\n                    if (bit_counter == 5'd0) begin\n                        n_mod_d <= remainder_temp;\n                        state <= LOOP_INIT;\n                    end\n                end\n\n                LOOP_INIT: begin\n                    i <= 8'd0;\n                    iB_total <= 16'd0;\n                    iB_mod_d <= 8'd0;\n                    state <= LOOP_BODY;\n                end\n\n                LOOP_BODY: begin\n                    if (iB_total > n_reg) begin\n                        state <= DONE;\n                    end else begin\n                        if (rem < min_rem) begin\n                            min_rem <= rem;\n                        end\n                        state <= LOOP_CHECK;\n                    end\n                end\n\n                LOOP_CHECK: begin\n                    i <= i + 8'd1;\n                    iB_total <= iB_total + B_reg;\n                    iB_mod_d <= (iB_mod_d + B_reg) % d_reg;\n                    if (i < (d_reg - 8'd1)) begin\n                        state <= LOOP_BODY;\n                    end else begin\n                        state <= DONE;\n                    end\n                end\n\n                DONE: begin\n                    result <= min_rem;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule